import {searchable,currentLanguage} from './i18n.js';
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createEventsPage(root,{portrait,onRegion}){
 let data=null,category='all',query='',access='all';
 const link=(url,text)=>`<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(text)} ↗</a>`;
 const date=(t,withTime=false)=>new Intl.DateTimeFormat(currentLanguage(),{timeZone:'Asia/Shanghai',year:'numeric',month:'short',day:'numeric',...(withTime?{hour:'2-digit',minute:'2-digit',hour12:false}:{})}).format(new Date(t*1000));
 const dateHTML=(t,withTime=false)=>`<time datetime="${new Date(t*1000).toISOString()}" data-event-date="${t}" data-event-with-time="${withTime}" data-no-translate>${escape(date(t,withTime))}</time>`;
 const characterStrip=e=>(e.characters||[]).length?`<div class="event-people" aria-label="故事人物">${e.characters.map(name=>`<button data-person="${escape(name)}" aria-label="阅读${escape(name)}的站内介绍">${portrait(name)}<span>${escape(name)}</span></button>`).join('')}</div>`:'';
 function matches(e){return(category==='all'||e.primary===category||e.related.includes(category))&&(access==='all'||(access==='stages'?e.stageAvailable:!e.stageAvailable))&&(!query||searchable([e.title,e.lineTitle,e.summary,...(e.synopsis||[]),...(e.characters||[]),data.categories.find(c=>c.id===e.primary)?.name,...e.related.map(id=>data.categories.find(c=>c.id===id)?.name)],query));}
 function readingLinks(e){
  if(!data.lines.find(line=>line.id===e.line)?.official)return '';
  const series=data.events.filter(item=>item.line===e.line).sort((a,b)=>a.order-b.order),index=series.findIndex(item=>item.id===e.id);
  if(series.length<2)return '';
  return `<div class="event-reading-links">${series[index-1]?`<button data-event-jump="${escape(series[index-1].id)}"><small>同乐章上一篇</small><span>← <span>${escape(series[index-1].title)}</span></span></button>`:''}${series[index+1]?`<button data-event-jump="${escape(series[index+1].id)}"><small>同乐章下一篇</small><span><span>${escape(series[index+1].title)}</span> →</span></button>`:''}</div><p class="event-reading-note">按本乐章目录衔接阅读，不代表泰拉历史上的先后时间。</p>`;
 }
 function eventCard(e){
  const c=data.categories.find(c=>c.id===e.primary);
  return `<article class="event-card" id="event-${escape(e.id)}" tabindex="-1"><div class="event-card-top"><span class="event-order">${String(e.order+1).padStart(2,'0')}</span><span class="event-access ${e.stageAvailable?'with-stages':''}">${e.collaboration?'已解锁剧情可回顾':e.stageAvailable?'剧情回顾 · 常驻关卡':'剧情回顾'}</span></div><h4>${escape(e.title)}</h4><button class="event-owner" data-event-category="${escape(c.id)}">${escape(c.kind)} / ${escape(c.name)}</button><p class="event-premise">${escape(e.summary)}</p>${characterStrip(e)}<div class="event-meta"><span><small>国服首次开放</small>${dateHTML(e.firstStart)}</span><span><small>剧情篇数</small><strong>${e.storyCount}</strong></span></div>${e.related.length?`<div class="event-related"><span>关联</span>${e.related.map(id=>{const r=data.categories.find(c=>c.id===id);return `<button data-event-category="${escape(id)}">${escape(r.name)}</button>`;}).join('')}</div>`:''}<details class="event-guide" data-event-guide="${escape(e.id)}"><summary>展开故事导读</summary><div class="event-synopsis">${(e.synopsis||[]).map(sentence=>`<p>${escape(sentence)}</p>`).join('')}</div>${readingLinks(e)}</details><details class="event-evidence" data-event-evidence="${escape(e.id)}"><summary>游戏内入口与资料来源</summary><p><span>游戏内：</span><span>${e.collaboration?'情报处理室／对应回顾条目':'终端 → 曲谱'}</span> → <span>${escape(e.title)}</span></p><p>${e.collaboration?'需此前已解锁对应剧情；未参加的账号不保证能够补解锁。':'需满足账号解锁条件；故事集可能需要事相碎片。'}</p><p>${e.stageAvailable?'关卡已收录常驻，仍需满足账号解锁条件。':'此处确认剧情收录，不代表战斗关卡或活动奖励当前开放。'}</p><p>${escape(e.basis)}</p><div class="event-source-links">${e.sources.map(s=>link(s.url,s.title)).join('')}</div></details></article>`;
 }
 function renderResults(){
  const opened=[...root.querySelectorAll('details[open][data-event-guide],details[open][data-event-evidence]')].map(e=>[e.hasAttribute('data-event-guide')?'data-event-guide':'data-event-evidence',e.dataset.eventGuide||e.dataset.eventEvidence]);
  const events=data.events.filter(matches),selected=data.categories.find(c=>c.id===category);
  root.querySelector('#event-count').textContent=`${events.length} 个故事`;
  root.querySelector('#event-selection').innerHTML=selected?`<span class="eyebrow">${escape(selected.kind)}</span><h2>${escape(selected.name)}</h2><p>${escape(selected.description)}</p>${selected.region?`<button data-event-map="${escape(selected.region)}">在大地图中查看 ↗</button>`:''}`:'<span class="eyebrow">STORY DIRECTORY</span><h2>从一片土地，走进一条故事线。</h2><p>按主要归属整理，保留关联地区。系列内沿用曲谱资料索引顺序，不作为剧情发生时间线；同一故事只收录一次。</p>';
  const groups=data.lines.map(l=>({...l,events:events.filter(e=>e.line===l.id)})).filter(l=>l.events.length);
  root.querySelector('#event-results').innerHTML=groups.length?groups.map(l=>`<section class="event-line"><header><div><span class="eyebrow">${escape(l.id)} / <span>${l.official?'游戏曲谱':'补充目录 · 非官方乐章'}</span></span><h3>${escape(l.title)}</h3></div><span>${l.events.length} 个故事</span></header><div class="event-cards">${l.events.map(eventCard).join('')}</div></section>`).join(''):'<div class="event-empty"><h3>没有找到符合条件的故事</h3><p>试试活动名、国家或组织名称，或清除筛选。</p><button data-event-reset>清除筛选</button></div>';
  for(const [key,id] of opened)root.querySelector(`details[${key}="${CSS.escape(id)}"]`)?.setAttribute('open','');
  root.querySelectorAll('[data-event-category]').forEach(b=>{b.classList.toggle('active',b.dataset.eventCategory===category);b.setAttribute('aria-pressed',String(b.dataset.eventCategory===category));});
 }
 function activeCard(e){
  const c=data.categories.find(c=>c.id===e.primary);
  return `<article class="event-current"><div><span class="eyebrow">当前活动 · 国服快照</span><h2>${escape(e.title)}</h2><button data-event-category="${escape(e.primary)}" class="event-owner">${escape(c?.name||e.primary)}</button><p>${escape(e.summary)}</p><div class="event-synopsis">${(e.synopsis||[]).map(s=>`<p>${escape(s)}</p>`).join('')}</div>${e.end?`<p class="event-current-dates"><span>战斗关卡开放至</span> ${dateHTML(e.end,true)}</p>`:''}<p class="event-current-dates"><span>剧情回顾开放</span> ${dateHTML(e.reviewStart,true)} <span>（北京时间）</span></p><p class="tiny">活动状态按资料核对日记录，实际开放以游戏内公告为准。</p>${c?.region?`<button class="chapter-link" data-event-map="${escape(c.region)}">查看相关地区档案 →</button>`:''}<div class="event-source-links">${e.sources.map(s=>link(s.url,s.title)).join('')}</div></div><div class="event-current-people">${characterStrip(e)}<span>点击人物，在本站阅读小传</span></div></article>`;
 }
 function render(){
  root.innerHTML=`<div class="events-wrap"><header class="events-intro"><div><span class="eyebrow">TERRA / STORIES BEYOND THE MAIN THEME</span><h1>大地上的故事</h1><p>追随人物的脚步，读懂一片土地的过去与现在。</p></div><div class="events-stamp"><span>可回顾的活动故事</span><strong>${data.events.length}</strong><small><span>资料核对</span> <span data-no-translate>${escape(data.checked)}</span></small></div></header>${(data.activeEvents||[]).map(activeCard).join('')}<div class="event-featured"><button data-event-category="babel" class="event-feature babel"><div><span class="eyebrow">RL / 方舟</span><h2>巴别塔</h2><p>从往昔的理想到罗德岛的旅程</p><span>查看这一条线 →</span></div><div class="event-feature-portrait">${portrait('特蕾西娅')}</div></button><button data-event-category="kjerag" class="event-feature kjerag"><div><span class="eyebrow">KJ / 山雪与银铁</span><h2>谢拉格</h2><p>风雪、列车与圣山之下的变革</p><span>查看这一条线 →</span></div><div class="event-feature-portrait">${portrait('银灰')}</div></button></div><div class="event-scope"><span>阅读指南</span><p>每篇收录故事概要、主要人物和两句导读。人物头像打开站内小传；同乐章前后篇便于接续阅读。导读含事件前提与部分剧情信息。</p><details><summary>范围与来源</summary><p>${escape(data.scope)}</p>${data.sources.map(s=>link(s.url,s.title)).join(' · ')}</details><details class="event-unavailable"><summary>暂不计入可回顾目录的活动（${data.excluded.length}）</summary><p><span>核对日</span>：<span data-no-translate>${escape(data.checked)}</span></p><p>${data.excluded.map(e=>`<span>${escape(e.title)}</span>`).join(' / ')}</p><p>这些条目尚未开放常驻剧情回顾；正在进行的活动按上方活动说明查看。</p></details></div><div class="event-browser"><aside class="event-filter" aria-label="活动归属筛选"><button data-event-category="all" class="active">全部故事 <span>${data.events.length}</span></button>${['组织','国家／地区','跨地区'].map(kind=>`<h3>${kind}</h3>${data.categories.filter(c=>c.kind===kind&&data.events.some(e=>e.primary===c.id||e.related.includes(c.id))).map(c=>`<button data-event-category="${escape(c.id)}">${escape(c.name)}<span>${data.events.filter(e=>e.primary===c.id||e.related.includes(c.id)).length}</span></button>`).join('')}`).join('')}</aside><div class="event-main"><div class="event-controls"><label><span class="sr-only">搜索活动故事</span><input id="event-search" type="search" placeholder="搜索故事、人物、国家或组织…" autocomplete="off"></label><label><span class="sr-only">活动可访问方式</span><select id="event-access"><option value="all">全部可回顾剧情</option><option value="stages">含常驻战斗关卡</option><option value="story">仅确认剧情回顾</option></select></label><button class="event-clear" data-event-reset>重置筛选</button><span id="event-count" role="status" aria-live="polite"></span></div><div id="event-selection"></div><div id="event-results"></div></div></div></div>`;
  root.querySelector('#event-search').value=query;root.querySelector('#event-access').value=access;renderResults();
 }
 root.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b)return;
  const behavior=matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth';
  if(b.hasAttribute('data-event-category')){category=b.dataset.eventCategory;renderResults();root.querySelector('.event-browser').scrollIntoView({behavior,block:'start'});}
  if(b.hasAttribute('data-event-reset')){category='all';query='';access='all';render();}
  if(b.dataset.eventMap)onRegion(b.dataset.eventMap);
  if(b.dataset.eventJump){const id=b.dataset.eventJump;category='all';query='';access='all';render();const card=root.querySelector('#event-'+CSS.escape(id));if(card){card.querySelector('.event-guide').open=true;card.focus({preventScroll:true});card.scrollIntoView({behavior,block:'center'});}}
 });
 root.addEventListener('input',e=>{if(e.target.id==='event-search'){query=e.target.value.trim();renderResults();}});
 root.addEventListener('change',e=>{if(e.target.id==='event-access'){access=e.target.value;renderResults();}});
 document.addEventListener('terramap-language',()=>{if(data&&!root.hidden){renderResults();root.querySelectorAll('[data-event-date]').forEach(el=>el.textContent=date(Number(el.dataset.eventDate),el.dataset.eventWithTime==='true'));}});
 return async()=>{if(data){render();return;}root.innerHTML='<div class="events-wrap" role="status">正在载入活动故事档案…</div>';try{const r=await fetch('events.json');if(!r.ok)throw Error(r.status);data=await r.json();render();}catch{root.innerHTML='<div class="events-wrap"><h1>活动档案暂时无法载入</h1><p>请检查本地服务后重新打开此页。</p></div>';}};
}
